static void module_kobj_release(struct kobject *kobj)
{
	struct module_kobject *mk = to_module_kobject(kobj);

	if (mk->kobj_completion)
		complete(mk->kobj_completion);

#ifdef CONFIG_MODULES
	if (mk->mod && mk == &mk->mod->mkobj)
		return;
#endif

	kfree(mk);
}

